from pathlib import Path


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    source = path.read_text(encoding="utf-8")
    count = source.count(old)
    if count != 1:
        raise SystemExit(f"{label} anchor count: {count}")
    path.write_text(source.replace(old, new, 1), encoding="utf-8")


def replace_between(path: Path, start: str, end: str, replacement: str, label: str) -> None:
    source = path.read_text(encoding="utf-8")
    start_index = source.find(start)
    if start_index < 0:
        raise SystemExit(f"{label} start anchor missing")
    end_index = source.find(end, start_index)
    if end_index < 0:
        raise SystemExit(f"{label} end anchor missing")
    path.write_text(source[:start_index] + replacement + source[end_index:], encoding="utf-8")


